from itertools import permutations
class Solution:
    def minimumString(self, a: str, b: str, c: str) -> str:
        def merge(x, y):
            k = min(len(x), len(y))
            while k > 0 and x[len(x) - k:] != y[:k]:
                k -= 1
            return x + y[k:]
        best = None
        for p in permutations([a, b, c]):
            s = merge(merge(p[0], p[1]), p[2])
            if best is None or (len(s), s) < (len(best), best):
                best = s
        return best

