class Solution {
public:
    string merge(const string& x, const string& y) {
        int k = min(x.size(), y.size());
        while (k > 0 && x.compare(x.size() - k, k, y, 0, k) != 0) k--;
        return x + y.substr(k);
    }
    string minimumString(string a, string b, string c) {
        vector<string> v = {a, b, c};
        sort(v.begin(), v.end());
        string best;
        do {
            string s = merge(merge(v[0], v[1]), v[2]);
            if (best.empty() || s.size() < best.size() || (s.size() == best.size() && s < best)) best = s;
        } while (next_permutation(v.begin(), v.end()));
        return best;
    }
};

