class Solution {
    private String merge(String x, String y) {
        int k = Math.min(x.length(), y.length());
        while (k > 0 && !x.substring(x.length() - k).equals(y.substring(0, k))) k--;
        return x + y.substring(k);
    }
    public String minimumString(String a, String b, String c) {
        String[] v = {a, b, c};
        Arrays.sort(v);
        String best = null;
        do {
            String s = merge(merge(v[0], v[1]), v[2]);
            if (best == null || s.length() < best.length() ||
                (s.length() == best.length() && s.compareTo(best) < 0)) best = s;
        } while (nextPerm(v));
        return best;
    }
    private boolean nextPerm(String[] v) {
        int i = v.length - 2;
        while (i >= 0 && v[i].compareTo(v[i + 1]) >= 0) i--;
        if (i < 0) return false;
        int j = v.length - 1;
        while (v[j].compareTo(v[i]) <= 0) j--;
        String t = v[i]; v[i] = v[j]; v[j] = t;
        for (int l = i + 1, r = v.length - 1; l < r; l++, r--) { t = v[l]; v[l] = v[r]; v[r] = t; }
        return true;
    }
}

