var minimumString = function(a, b, c) {
    const merge = (x, y) => {
        let k = Math.min(x.length, y.length);
        while (k > 0 && x.slice(x.length - k) !== y.slice(0, k)) k--;
        return x + y.slice(k);
    };
    let best = null;
    for (const p of [[a,b,c],[a,c,b],[b,a,c],[b,c,a],[c,a,b],[c,b,a]]) {
        const s = merge(merge(p[0], p[1]), p[2]);
        if (best === null || s.length < best.length ||
            (s.length === best.length && s < best)) best = s;
    }
    return best;
};
